-- Posts
INSERT INTO public.posts (title, slug, content, excerpt, category, rating, reading_time, is_published, published_at, created_at) VALUES
(
  'Как я строю продукты: от хаоса к системе',
  'kak-ya-stroyu-produkty',
  E'## Введение\n\nКогда ты основал больше десяти продуктов, начинаешь замечать паттерны. Не те, о которых пишут в учебниках, а настоящие — грязные, неудобные, но работающие.\n\n> Лучший продукт — тот, который решает проблему, о которой пользователь ещё не знает.\n\n## Первый принцип: скорость важнее качества\n\nНа ранней стадии **скорость** — это всё. Не потому что качество не важно, а потому что без скорости вы не доживёте до момента, когда качество начнёт играть роль.\n\n### Что это значит на практике\n\n- MVP за 2 недели, не за 2 месяца\n- Используйте no-code там, где можно\n- Автоматизируйте только то, что делаете больше 3 раз\n\n## Второй принцип: команда > идея\n\nХорошая команда с плохой идеей победит плохую команду с хорошей идеей. Всегда.\n\n```\nФормула успеха:\nКоманда × Рынок × Время > Идея × Деньги\n```\n\nПродолжение следует...',
  'Когда ты основал больше десяти продуктов, начинаешь замечать паттерны. Не те, о которых пишут в учебниках, а настоящие.',
  'thoughts', NULL, 5, true, '2026-02-15T10:00:00Z', '2026-02-15T10:00:00Z'
),
(
  '«Думай медленно, решай быстро» — Даниэль Канеман',
  'dumaj-medlenno-reshaj-bystro',
  E'## О книге\n\nКанеман разделяет мышление на две системы: быструю интуитивную (Система 1) и медленную аналитическую (Система 2).\n\n## Ключевые идеи\n\n1. **Эффект якоря** — первая увиденная цифра влияет на все последующие оценки\n2. **Эвристика доступности** — мы переоцениваем вероятность событий, которые легко вспомнить\n3. **Ошибка планирования** — мы систематически недооцениваем время и ресурсы\n\n> Мы слишком уверены в том, что знаем, и неспособны признать масштаб своего незнания.\n\n## Применение в бизнесе\n\nПонимание когнитивных искажений — суперсила предпринимателя. Когда ты знаешь, что мозг врёт — ты можешь это компенсировать.',
  'Канеман разделяет мышление на две системы: быструю интуитивную и медленную аналитическую. Почему это важно для предпринимателей.',
  'books', 9, 4, true, '2026-02-10T10:00:00Z', '2026-02-10T10:00:00Z'
),
(
  'Принцип радикальной прозрачности',
  'printsip-radikalnoj-prozrachnosti',
  E'## Что это\n\nРадикальная прозрачность — это когда вся команда видит всё: цифры, проблемы, ошибки, зарплаты.\n\n## Почему это работает\n\n- Люди принимают лучшие решения, когда владеют полной информацией\n- Доверие строится не на словах, а на открытости\n- Проблемы решаются быстрее, когда о них знают все\n\n## Как внедрить\n\n1. Открыть доступ к метрикам для всей команды\n2. Обсуждать ошибки без обвинений\n3. Делиться финансовыми результатами ежемесячно',
  'Радикальная прозрачность — когда вся команда видит всё. Почему это сложно, но невероятно эффективно.',
  'principles', NULL, 3, true, '2026-02-05T10:00:00Z', '2026-02-05T10:00:00Z'
),
(
  'Мета-мышление: как думать о том, как ты думаешь',
  'meta-myshlenie',
  E'## Рефлексия над процессом мышления\n\nБольшинство людей думают о проблемах. Немногие думают о том, *как* они думают о проблемах. Именно этот второй уровень отличает великих предпринимателей.\n\n## Практики мета-мышления\n\n- **Ведение журнала решений** — записывайте свою логику на момент принятия решения\n- **Post-mortem без обвинений** — анализ не того, кто виноват, а того, какой процесс привёл к ошибке\n- **Второй мозг** — система для хранения и связывания идей',
  'Большинство людей думают о проблемах. Немногие думают о том, как они думают о проблемах.',
  'meta', NULL, 4, true, '2026-02-01T10:00:00Z', '2026-02-01T10:00:00Z'
),
(
  'Подборка: 5 инструментов для продуктовых команд',
  'instrumenty-dlya-produktovyh-komand',
  E'## Инструменты, которые реально работают\n\n1. **Linear** — лучший трекер задач для стартапов\n2. **Notion** — база знаний и документация\n3. **Figma** — прототипирование и дизайн\n4. **Mixpanel** — продуктовая аналитика\n5. **Intercom** — поддержка и онбординг',
  '5 инструментов, которые мы используем каждый день в наших продуктовых командах.',
  'links', NULL, 2, true, '2026-01-28T10:00:00Z', '2026-01-28T10:00:00Z'
),
(
  '«От нуля к единице» — Питер Тиль',
  'ot-nulya-k-edinitse',
  E'## Главная мысль\n\nТиль утверждает, что настоящий прогресс — это создание чего-то принципиально нового (от 0 к 1), а не копирование существующего (от 1 к n).\n\n## Монополия > конкуренция\n\n> Конкуренция — для лузеров. Стремитесь к монополии.\n\nЗвучит провокационно, но логика железная: в конкурентном рынке маржа стремится к нулю.',
  'Настоящий прогресс — это создание чего-то принципиально нового, а не копирование существующего.',
  'books', 8, 3, true, '2026-01-20T10:00:00Z', '2026-01-20T10:00:00Z'
);

