INSERT INTO public.context_entries (category, title, content, is_active) VALUES
('bio', 'Обо мне', 'Данил Кочнев, 27 лет. Серийный IT-предприниматель с 2018 года. Основал и развил более 6 продуктов — от рекламных технологий до fashion-tech и AI. Образование: СПбГУ, МФТИ, Product University, YC Startup School. Верю в синтез знаний из разных областей.', true),
('product', 'MakeMeLook', 'AI virtual try-on платформа. B2B SaaS для fashion-ритейла. Позволяет покупателям примерять одежду и аксессуары через нейросеть. Статус: активный. Текущий фокус: масштабирование продаж, интеграции с маркетплейсами.', true),
('product', 'CarSwap AI', 'Инструмент для перекраски автомобилей на фото с помощью AI. Целевая аудитория: автодилеры, детейлинг-студии. Статус: активный. Стадия: поиск product-market fit.', true),
('product', 'THE MONO', 'B2B маркетплейс для fashion-индустрии. Связывает бренды с байерами и шоурумами. Статус: пауза. Причина: фокус на MakeMeLook и CarSwap.', false),
('product', 'Cursor for Founders', 'AI-воркспейс для серийных предпринимателей. Объединяет контекст всех проектов, трекинг спринтов и генерацию контента. Статус: разработка.', true),
('trend', 'Тренды и цели Q1 2026', 'Тренды: AI-агенты для бизнеса, персонализация через LLM, building in public. Цели: выйти на 500K MRR по MakeMeLook, запустить MVP Cursor for Founders, начать регулярно вести блог.', true);
